// writeShortHelp prints Use, Short, local flags, examples, and subcommands
// without the inherited global flag list. Use --help-all for full help.
func writeShortHelp(w io.Writer, cmd *cobra.Command) {
	fmt.Fprintf(w, "Usage:\n  %s\n\n", cmd.UseLine())
	if cmd.HasParent() {
		if cmd.Short != "" {
			fmt.Fprintf(w, "%s\n\n", cmd.Short)
		}
	} else if cmd.Long != "" {
		fmt.Fprintf(w, "%s\n\n", strings.TrimSpace(cmd.Long))
	} else if cmd.Short != "" {
		fmt.Fprintf(w, "%s\n\n", cmd.Short)
	}
	if cmd.HasAvailableSubCommands() {
		fmt.Fprintf(w, "Available Commands:\n")
		for _, c := range cmd.Commands() {
			if !c.IsAvailableCommand() || c.Hidden {
				continue
			}
			fmt.Fprintf(w, "  %-16s %s\n", c.Name(), c.Short)
		}
		fmt.Fprintln(w)
	}
	if cmd.HasParent() {
		local := cmd.NonInheritedFlags()
		if local != nil && local.HasAvailableFlags() {
			fmt.Fprintf(w, "Flags:\n%s\n", local.FlagUsages())
		}
	}
	if cmd.Example != "" {
		fmt.Fprintf(w, "Examples:\n%s\n\n", cmd.Example)
	}
	fmt.Fprintf(w, "Use \"%s --help-all\" to show global flags.\n", cmd.CommandPath())
}

func ExitCode(err error) int {
	var codeErr *cliError
	if As(err, &codeErr) {
		return codeErr.code
	}
	return 1
}

func (f *rootFlags) newClient() (*client.Client, error) {
	cfg, err := config.Load(f.configPath)
	if err != nil {
		return nil, configErr(err)
	}
	c := client.New(cfg, f.timeout, f.rateLimit)
	c.DryRun = f.dryRun
	c.NoCache = f.noCache
	return c, nil
}

func (f *rootFlags) printJSON(w *cobra.Command, v any) error {
	return printJSONFiltered(w.OutOrStdout(), v, f)
}

func (f *rootFlags) printTable(w *cobra.Command, headers []string, rows [][]string) error {
	if f.asJSON {
		return fmt.Errorf("use printJSON for JSON output")
	}
	tw := tabwriter.NewWriter(w.OutOrStdout(), 2, 4, 2, ' ', 0)
	header := ""
	for i, h := range headers {
		if i > 0 {
			header += "\t"
		}
		header += h
	}
	fmt.Fprintln(tw, header)
	for _, row := range rows {
		line := ""
		for i, cell := range row {
			if i > 0 {
				line += "\t"
			}
			line += cell
		}
		fmt.Fprintln(tw, line)
	}
	return tw.Flush()
}
